import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEco5,validEco5,advanceEco5,numericEco5,policies,planTotals,planValid,pyramidValid,allocationValid,supplyCases,supplyResult,supplyValid}from './eco5-models.js?v=20261023-physicscomplete01';import{showEco5}from './eco5-visuals.js?v=20261023-physicscomplete01';export{showEco5};
export function mountEco5(l,p,root,{save,done,feedback}){let ts=tasksForEco5(l.widget.slice(5)),w=p.widget;w.eco5Task??=ts[0].id;w.eco5Drafts??={};w.eco5Passed??=[];let i=ts.findIndex(t=>t.id===w.eco5Task);if(i<0)i=0;let t=ts[i],v=w.eco5Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEco5(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.eco5Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('eco5Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('eco5Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEco5">Reveal evidence →</button><p id="eco5Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEco5(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#eco5Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEco5(c,v.answer);}
else if(t.type==='sequence'){body=field('eco5Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEco5">Advance pathway →</button><p id="eco5Readout" aria-live="polite"></p>';draw=()=>{showEco5(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#eco5Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='plan'){v.selected??=[];body='<p>Budget 10 credits. Targets: at least 4 ha habitat and 20 tonnes waste diverted. Fictional outcomes; breeding has other benefits outside these targets.</p>'+Object.entries(policies).map(([k,n])=>'<label class="field-label"><input type="checkbox" id="eco5Policy-'+k+'" '+(v.selected.includes(k)?'checked':'')+'> '+n.label+' ·'+n.cost+' credits ·'+n.habitat+' ha ·'+n.waste+' tonnes</label>').join('')+field('eco5Reason','Interpretation',[['bounded','Meets these stated goals; not a universal best policy'],['universal','Proves all other conservation is useless']],v.reason);draw=()=>showEco5(t.kind,{selected:v.selected,title:t.title});valid=()=>planValid(v);}
else if(t.type==='pyramid'){v.masses??=Array(4).fill('');body='<p>Supplied producer/primary/secondary/tertiary masses: 800,160,32,6.4 g/m². Use one linear width scale.</p>'+field('eco5Base','Base level',[['producers','Producers'],['tertiary','Tertiary consumers']],v.base)+field('eco5Scale','Biomass represented by the full width',[['100','100 g/m²'],['1000','1000 g/m²'],['200','200 g/m²']],v.scale)+['Producer','Primary','Secondary','Tertiary'].map((n,j)=>'<label class="field-label">'+n+' / g/m²<input class="lab-input" id="eco5Mass-'+j+'" type="number" step="any" value="'+v.masses[j]+'"></label>').join('');draw=()=>showEco5(t.kind,{masses:v.masses,scale:Number(v.scale||1000),base:v.base,title:t.title});valid=()=>pyramidValid(v);}
else if(t.type==='allocation'){body='<p>Original 100 consumed organic-material units: 20 unabsorbed,70 substrate used in respiration,10 retained as growth. Enter the three branches; this excludes incoming oxygen/product masses and urinary routes.</p>'+[['Faeces','faeces'],['Respired','respired'],['Growth','growth']].map(([label,key])=>'<label class="field-label">'+label+' / organic-material units<input class="lab-input" id="eco5'+label+'" type="number" step="any" value="'+(v[key]??'')+'"></label>').join('')+field('eco5Reason','Boundary',[['organic','Tracks original organic material; not total gas/product mass'],['destroyed','Material missing from growth is destroyed']],v.reason);draw=()=>showEco5(t.kind,{allocation:v,title:t.title});valid=()=>allocationValid(v);}
else if(t.type==='supply'){v.scenario??='baseline';v.observed??=[];body='<p>Each model person needs 2 food-equivalent units. Compare accessible supply with demand; production and access can differ. Original fictional data, not nutrition advice.</p>'+field('eco5Scenario','Scenario',Object.entries(supplyCases).map(([k,n])=>[k,n.label]),v.scenario)+'<label class="field-label">Predict shortfall / units<input class="lab-input" type="number" id="eco5Predict" value="'+(v.prediction??'')+'"></label><button class="secondary" id="eco5Run">Reveal comparison →</button>'+field('eco5Reason','Conclusion',[['limited','Aggregate toy deficit; access and nutrition need further evidence'],['all','Enough production proves everybody is well fed']],v.reason);draw=()=>showEco5(t.kind,{scenario:v.scenario,revealed:v.ran,title:t.title});valid=()=>!!v.ran&&numericEco5(v.prediction,supplyResult(v.scenario).shortfall);}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="eco5Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="eco5Number" type="number" step="any" value="'+(v.number??'')+'">'+field('eco5Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEco5(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEco5(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="eco5Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEco5">Record reasoning</button><button class="secondary" id="nextEco5">Next challenge →</button></div><p id="eco5Progress"></p>';
const status=()=>{$('#eco5Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='supply'?'Recorded: '+v.observed.join(', '):w.eco5Passed.includes(t.id)?'Challenge recorded.':'';$('#eco5Progress').textContent=ts.filter(t=>w.eco5Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id.startsWith('eco5Policy-')){let k=id.slice(11);v.selected=e.target.checked?[...new Set([...v.selected,k])]:v.selected.filter(x=>x!==k);save();draw();return;}if(id.startsWith('eco5Mass-')){v.masses[Number(id.split('-')[1])]=val;save();draw();return;}if(id==='eco5Scale'||id==='eco5Base'){v[id==='eco5Scale'?'scale':'base']=val;save();draw();return;}if(id==='eco5Scenario'){if(!val)return;v.scenario=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='eco5Predict'){v.prediction=val;save();return;}if(['eco5Faeces','eco5Respired','eco5Growth'].includes(id)){v[id.slice(4).toLowerCase()]=val;save();draw();return;}if(id==='eco5Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='eco5Answer')v.answer=val;else if(id==='eco5Next')v.next=val;else if(id==='eco5Number')v.number=val;else if(id==='eco5Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{let id=e.target.id;if(id.startsWith('eco5Mass-'))v.masses[Number(id.split('-')[1])]=e.target.value;else if(id==='eco5Predict')v.prediction=e.target.value;else if(['eco5Faeces','eco5Respired','eco5Growth'].includes(id))v[id.slice(4).toLowerCase()]=e.target.value;else v.number=e.target.value;save();if(['pyramid','allocation'].includes(t.type))draw();};}
if($('#eco5Run'))$('#eco5Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a numerical shortfall first.',true);return;}v.ran=true;save();draw();};
if($('#revealEco5'))$('#revealEco5').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEco5(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEco5(t.cases[v.case],v.answer));};
if($('#advanceEco5'))$('#advanceEco5').onclick=()=>{let n=advanceEco5(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEco5').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='supply'&&!v.observed.includes(v.scenario))v.observed.push(v.scenario);let finished=t.type==='supply'?supplyValid(v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.eco5Passed.includes(t.id))w.eco5Passed.push(t.id);p.widgetDone=ts.every(t=>w.eco5Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEco5').onclick=()=>{if(!w.eco5Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.eco5Task=ts[(i+1)%ts.length].id;save();remount();};}
